const z = require("zod");
const { optionalFutureDate } = require("./helpers");
const { fileIdParamSchema } = require("./file.validator");

// Share tokens are generated by the server as URL-safe base64url strings.
const shareTokenParamSchema = z.object({
  token: z
    .string()
    .trim()
    .min(1, "Share token is required")
    .max(128, "Share token is too long")
    .regex(/^[A-Za-z0-9_-]+$/, "Invalid share token"),
});

// POST /api/files/:id/share body: expiresAt is optional ("" / null = no expiry).
const createShareSchema = z.object({
  expiresAt: optionalFutureDate,
});

module.exports = { fileIdParamSchema, shareTokenParamSchema, createShareSchema };